class Solution {
    func change(_ amount: Int, _ coins: [Int]) -> Int {
        var dp = [Int](repeating: 0, count: amount + 1)
        dp[0] = 1

        for i in stride(from: coins.count - 1, through: 0, by: -1) {
            for a in 1..<(amount + 1) {
                if coins[i] <= a {
                    let addend = dp[a - coins[i]]
                    if dp[a] > Int.max - addend {
                        dp[a] = 0
                    } else {
                        dp[a] += addend
                    }
                }
            }
        }

        return dp[amount]
    }
}

